window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-907224befbce2dc0"]={"versions": [{"id": "FIG-907224befbce2dc0", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Schaubild ist ein Architektur- und Interaktionsdiagramm im Kontext der AUTOSAR-Classic-Diagnosekommunikation (DCM - Diagnostic Communication Manager und DEM - Diagnostic Event Manager). Es visualisiert die Bearbeitung des UDS-Dienstes 0x19 mit Subfunktion 0x03 (Read DTC Information - Report DTC Snapshot Record Identification) zwischen einem externen Tester und den Basissoftware-Modulen DCM und DEM sowie den Zugriff auf den Ereignisspeicher (Event memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li>External Tester: Diagnose-Client, der UDS-Dienst-Requests sendet und Responses empfängt.</li>\n<li>DCM: AUTOSAR-BSW-Modul für das Diagnoseprotokoll-Handling.</li>\n<li>DEM: AUTOSAR-BSW-Modul zur Verwaltung von Diagnosereferenzen, Fehlerspeichern und Freeze-Frames (Event memory).</li>\n<li>Schnittstellen:</li>\n<li>Tester-DCM: UDS-Dienst 0x19 (Subfunktion 0x03) ohne Parameter; Response-Dienst 0x59 0x03 mit Parametern (DTC + RecordNumber(s), DTC2 + ...).</li>\n<li>DCM-DEM: C-Funktionsaufruf <code>Dem_GetDTCOfFreezeFrameRecord</code> durch DCM an DEM mit synchronem Rückgabewert <code>DTC</code>.</li>\n<li>Datenstrukturen im DEM: Tabellarischer Ereignisspeicher mit 9 Record-Slots (1 bis 9) aufgeteilt nach DTC1 (FreezeFrame 1st set, FreezeFrame 2nd set, free), DTC2 (FreezeFrame 1st set, free, free) und ungenutzten Slots (free). Eine Beispielzeile demonstriert die Zuordnung absoluter Record-Nummern zu DTCs bzw. Fehlerfällen (NoDTC ForRecord, Wrong Record).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanforderung <code>Request: $19 $03 (no parameter)</code> an das DCM.</li>\n<li>Das DCM iteriert in einer internen Schleife über alle potenziellen Record-Nummern (<code>For RecordNumber 1 ... FE</code>).</li>\n<li>Je Iterationsschritt ruft das DCM die Schnittstelle <code>Dem_GetDTCOfFreezeFrameRecord</code> am DEM auf.</li>\n<li>Das DEM prüft die übergebene Record-Nummer gegen den Event memory und liefert den zugehörigen Rückgabewert <code>DTC</code> (bzw. DTC1, DTC2, NoDTC ForRecord, Wrong Record) an das DCM zurück.</li>\n<li>Nach Durchlauf der Iteration aggregiert das DCM die Ergebnisse und sendet die positive UDS-Antwort <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code> an den externen Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Record-Nummern müssen im DEM absolut adressiert sein („RecordNumbers must be absolute“).</li>\n<li>Der DCM fragt jeden Freeze-Frame-Record über seinen festen Nummernkreis (1 bis 0xFE) einzeln per Funktionsaufruf ab.</li>\n<li>Das DCM aggregiert DTC-Werte und zugehörige Snapshot-RecordNumbers in einer zusammenhängenden Diagnoseantwort gemäß UDS ISO 14229.</li>\n</ul>"}, {"id": "FIG-c00fbae341a9f7a6", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Schaubild ist ein Architektur- und Interaktionsdiagramm im Kontext der AUTOSAR-Classic-Diagnosekommunikation (DCM - Diagnostic Communication Manager und DEM - Diagnostic Event Manager). Es visualisiert die Bearbeitung des UDS-Dienstes 0x19 mit Subfunktion 0x03 (Read DTC Information - Report DTC Snapshot Record Identification) zwischen einem externen Tester und den Basissoftware-Modulen DCM und DEM sowie den Zugriff auf den Ereignisspeicher (Event memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li>External Tester: Diagnose-Client, der UDS-Dienst-Requests sendet und Responses empfängt.</li>\n<li>DCM: AUTOSAR-BSW-Modul für das Diagnoseprotokoll-Handling.</li>\n<li>DEM: AUTOSAR-BSW-Modul zur Verwaltung von Diagnosereferenzen, Fehlerspeichern und Freeze-Frames (Event memory).</li>\n<li>Schnittstellen:</li>\n<li>Tester-DCM: UDS-Dienst 0x19 (Subfunktion 0x03) ohne Parameter; Response-Dienst 0x59 0x03 mit Parametern (DTC + RecordNumber(s), DTC2 + ...).</li>\n<li>DCM-DEM: C-Funktionsaufruf <code>Dem_GetDTCOfFreezeFrameRecord</code> durch DCM an DEM mit synchronem Rückgabewert <code>DTC</code>.</li>\n<li>Datenstrukturen im DEM: Tabellarischer Ereignisspeicher mit 9 Record-Slots (1 bis 9) aufgeteilt nach DTC1 (FreezeFrame 1st set, FreezeFrame 2nd set, free), DTC2 (FreezeFrame 1st set, free, free) und ungenutzten Slots (free). Eine Beispielzeile demonstriert die Zuordnung absoluter Record-Nummern zu DTCs bzw. Fehlerfällen (NoDTC ForRecord, Wrong Record).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanforderung <code>Request: $19 $03 (no parameter)</code> an das DCM.</li>\n<li>Das DCM iteriert in einer internen Schleife über alle potenziellen Record-Nummern (<code>For RecordNumber 1 ... FE</code>).</li>\n<li>Je Iterationsschritt ruft das DCM die Schnittstelle <code>Dem_GetDTCOfFreezeFrameRecord</code> am DEM auf.</li>\n<li>Das DEM prüft die übergebene Record-Nummer gegen den Event memory und liefert den zugehörigen Rückgabewert <code>DTC</code> (bzw. DTC1, DTC2, NoDTC ForRecord, Wrong Record) an das DCM zurück.</li>\n<li>Nach Durchlauf der Iteration aggregiert das DCM die Ergebnisse und sendet die positive UDS-Antwort <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code> an den externen Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Record-Nummern müssen im DEM absolut adressiert sein („RecordNumbers must be absolute“).</li>\n<li>Der DCM fragt jeden Freeze-Frame-Record über seinen festen Nummernkreis (1 bis 0xFE) einzeln per Funktionsaufruf ab.</li>\n<li>Das DCM aggregiert DTC-Werte und zugehörige Snapshot-RecordNumbers in einer zusammenhängenden Diagnoseantwort gemäß UDS ISO 14229.</li>\n</ul>"}, {"id": "FIG-3a4c10aaf37d6eee", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Schaubild ist ein Architektur- und Interaktionsdiagramm im Kontext der AUTOSAR-Classic-Diagnosekommunikation (DCM - Diagnostic Communication Manager und DEM - Diagnostic Event Manager). Es visualisiert die Bearbeitung des UDS-Dienstes 0x19 mit Subfunktion 0x03 (Read DTC Information - Report DTC Snapshot Record Identification) zwischen einem externen Tester und den Basissoftware-Modulen DCM und DEM sowie den Zugriff auf den Ereignisspeicher (Event memory).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li>External Tester: Diagnose-Client zur Übertragung von Diagnoserequests und Empfang von Serviceresponses.</li>\n<li>DCM: Diagnosesteuerungsmodul zur Abwicklung des Diagnoseprotokolls und Filterung von Records.</li>\n<li>DEM: Diagnose-Ereignisspeicher zur Verwaltung gespeicherter DTCs und Freeze-Frames.</li>\n<li>Schnittstellen:</li>\n<li>Tester-DCM: Diagnoserequest <code>Request: $19 $03 (no parameter)</code> und Diagnoseantwort <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>.</li>\n<li>DCM-DEM: C-Funktionsaufruf <code>Dem_SetDTCFilterForRecords</code> zur Initialisierung des Record-Filters mit Rückgabewert <code>NumberOfFilteredRecords</code>; C-Funktionsaufruf <code>Dem_GetNextFilteredRecord</code> zum sukzessiven Auslesen gefilterter Records mit Rückgabewert <code>DTC</code>.</li>\n<li>Datenstrukturen im DEM: Tabellarischer Ereignisspeicher mit Record-Slots für Freeze-Frames zu DTC1, DTC2 und freien Einträgen sowie einer Zuordnungsmatrix für gefilterte Record-Abfragen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanfrage <code>Request: $19 $03 (no parameter)</code> an das DCM.</li>\n<li>Das DCM ruft initial die Funktion <code>Dem_SetDTCFilterForRecords</code> am DEM auf.</li>\n<li>Das DEM liefert als Rückgabewert die Anzahl zutreffender Records (<code>NumberOfFilteredRecords</code>) zurück.</li>\n<li>Das DCM führt eine Schleife über die ermittelte Anzahl (<code>NumberOfFilteredRecords</code>) aus.</li>\n<li>In jedem Schleifendurchlauf ruft das DCM die Funktion <code>Dem_GetNextFilteredRecord</code> am DEM auf.</li>\n<li>Das DEM liefert den jeweiligen <code>DTC</code> für den nächsten gefilterten Datensatz an das DCM zurück.</li>\n<li>Das DCM konsolidiert die DTCs und Record-Nummern und antwortet dem Tester mit <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Record-Nummern sind absolut definiert („RecordNumbers must be absolute“).</li>\n<li>Das DCM iteriert nicht mehr blind über den gesamten Wertebereich (1 bis 0xFE), sondern filtert vorab über <code>Dem_SetDTCFilterForRecords</code> und liest nur die tatsächliche Anzahl gefilterter Records (<code>NumberOfFilteredRecords</code>) über <code>Dem_GetNextFilteredRecord</code> aus.</li>\n<li>Gewährleistet ein standardisiertes Filter- und Iterator-Pattern zwischen DCM und DEM zur Reduktion von IPC- und Ausführungsaufwand.</li>\n</ul>"}, {"id": "FIG-f75b8201329a943c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Schaubild ist ein kombiniertes Spezifikations- und Interaktionsdiagramm im AUTOSAR-Classic-DCM-Kontext. Es definiert verbindlich über die Anforderungsbox Dcm300 das Format der positiven Diagnoseantwort für den UDS-Service 0x19 Subfunktion 0x03 und illustriert die Interaktion zwischen externem Diagnosetester, DCM und DEM sowie den Zugriff auf den DEM-Ereignisspeicher.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li>External Tester: Diagnose-Client zur Übertragung von Diagnoserequests und Empfang von Serviceresponses.</li>\n<li>DCM: Diagnosesteuerungsmodul zur Abwicklung des Diagnoseprotokolls und Filterung von Records.</li>\n<li>DEM: Diagnose-Ereignisspeicher zur Verwaltung gespeicherter DTCs und Freeze-Frames.</li>\n<li>Schnittstellen:</li>\n<li>Tester-DCM: Diagnoserequest <code>Request: $19 $03 (no parameter)</code> und Diagnoseantwort <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>.</li>\n<li>DCM-DEM: C-Funktionsaufruf <code>Dem_SetDTCFilterForRecords</code> zur Initialisierung des Record-Filters mit Rückgabewert <code>NumberOfFilteredRecords</code>; C-Funktionsaufruf <code>Dem_GetNextFilteredRecord</code> zum sukzessiven Auslesen gefilterter Records mit Rückgabewert <code>DTC</code>.</li>\n<li>Datenstrukturen im DEM: Tabellarischer Ereignisspeicher mit Record-Slots für Freeze-Frames zu DTC1, DTC2 und freien Einträgen sowie einer Zuordnungsmatrix für gefilterte Record-Abfragen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der externe Tester sendet die Diagnoseanfrage <code>Request: $19 $03 (no parameter)</code> an das DCM.</li>\n<li>Das DCM ruft initial die Funktion <code>Dem_SetDTCFilterForRecords</code> am DEM auf.</li>\n<li>Das DEM liefert als Rückgabewert die Anzahl zutreffender Records (<code>NumberOfFilteredRecords</code>) zurück.</li>\n<li>Das DCM führt eine Schleife über die ermittelte Anzahl (<code>NumberOfFilteredRecords</code>) aus.</li>\n<li>In jedem Schleifendurchlauf ruft das DCM die Funktion <code>Dem_GetNextFilteredRecord</code> am DEM auf.</li>\n<li>Das DEM liefert den jeweiligen <code>DTC</code> für den nächsten gefilterten Datensatz an das DCM zurück.</li>\n<li>Das DCM konsolidiert die DTCs und Record-Nummern und antwortet dem Tester mit <code>Response: $59 $03 (DTC + RecordNumber(s), DTC2 + ...)</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Anforderung Dcm300 verpflichtet das DCM-Modul bei einer positiven Antwort auf UDS Service 0x19 mit Subfunktion 0x03, die Parameter <code>DTCRecord/ DTCSnapshotRecordNumber</code> gemäß Festlegung in <code>Dcm299</code> in die Antwortnachricht aufzunehmen.</li>\n<li>Record-Nummern müssen im DEM absolut vorgehalten werden („RecordNumbers must be absolute“).</li>\n<li>Die Abfrage der Datensätze erfolgt verbindlich über das Filter-Iterator-Paar <code>Dem_SetDTCFilterForRecords</code> (liefert <code>NumberOfFilteredRecords</code>) und <code>Dem_GetNextFilteredRecord</code> (liefert <code>DTC</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-907224befbce2dc0", "to": "FIG-c00fbae341a9f7a6", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textkorrektur unterhalb der DEM-Box: Tippfehler „RecordNumbers must be absolut“ wurde zu „RecordNumbers must be absolute“ korrigiert; das isolierte Zeichen „e“ am rechten unteren Rand entfällt.</li>\n<li>Wegfall der doppelten Kapitelüberschrift („G.) Read DTC Information / Report DTC Snapshot Record Identification“) über dem Diagramm.</li>\n</ul>"}, {"from": "FIG-c00fbae341a9f7a6", "to": "FIG-3a4c10aaf37d6eee", "fr": "R3.0.7", "tr": "R3.1.5", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Änderung der internen Dem-Schnittstelle: Statt <code>Dem_GetDTCOfFreezeFrameRecord</code> (Aufruf in einer Schleife <code>For RecordNumber 1 ... FE</code>) wird nun initial <code>Dem_SetDTCFilterForRecords</code> aufgerufen, das <code>NumberOfFilteredRecords</code> zurückgibt.</li>\n<li>Zur iterativen Abfrage wird die Schnittstelle <code>Dem_GetNextFilteredRecord</code> mit Rückgabewert <code>DTC</code> eingeführt, die in einer Schleife über <code>NumberOfFilteredRecords</code> aufgerufen wird.</li>\n<li>Wegfall der textuellen Schleifenbedingung <code>For RecordNumber 1 ... FE</code> im DCM zugunsten von <code>NumberOfFilteredRecords</code>.</li>\n</ul>"}, {"from": "FIG-3a4c10aaf37d6eee", "to": "FIG-f75b8201329a943c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der normativen Spezifikationsanforderung Dcm300 samt Parametertabelle über dem Interaktionsdiagramm: Festlegung der Antwortdaten für UDS Service 0x19 Subfunktion 0x03 (<code>Parameter name</code>: DTCRecord/ DTCSnapshotRecordNumber, <code>Value</code>: As defined in Dcm299).</li>\n</ul>"}]};
